const OF_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return OF_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const OF_dbl=(x1,y,x2,col,w=3)=>OF_arrow((x1+x2)/2,y,x1,y,col,w)+OF_arrow((x1+x2)/2,y,x2,y,col,w);
const OF_R=d=>d*Math.PI/180;
const OF_GREY='#5C6577', OF_CORE='#DBE4FF', OF_CLAD='#F1F3F5';
const OF_poly=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const OF_fn=(x0,x1,f,n=120)=>{const p=[];for(let i=0;i<=n;i++){const x=x0+(x1-x0)*i/n;p.push([x,f(x)])}return p};
/* the book's numbers, computed once */
const OF_D=(1.48*1.48-1.46*1.46)/(2*1.48*1.48);              // Δ = 0.01342
const OF_V1=2*Math.PI*25/1.30*Math.sqrt(1.48*1.48-1.46*1.46); // V = 29.30
const OF_K2=2*Math.PI*4*0.11;                                 // 2πa·NA = 2.765 µm
const OF_n=r=>Math.abs(r)>=25?1.46:1.48*Math.sqrt(1-2*OF_D*(r/25)*(r/25));   // parabolic profile, a = 25 µm
/* a fiber side-on: core between yc-hc and yc+hc, cladding cw each side */
const OF_fiber=(x0,x1,yc,hc,cw,core=OF_CORE)=>`<rect x="${x0}" y="${yc-hc-cw}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc+hc}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc-hc}" width="${x1-x0}" height="${2*hc}" fill="${core}" stroke="${BLU}" stroke-width="2"/>`;
const OF_zig=(x0,x1,yc,hc,tr,col,w=4)=>{let p=[[x0,yc]],x=x0,y=yc,dir=-1,t=Math.tan(OF_R(tr));for(let k=0;k<60&&x<x1;k++){const yw=yc+dir*hc,dx=Math.abs(yw-y)/t;if(x+dx>=x1){p.push([x1,y+dir*(x1-x)*t]);x=x1;break}x+=dx;y=yw;p.push([x,y]);dir=-dir}return OF_poly(p,col,w)};
const OF_wave=(x0,x1,yc,A,P,col,w=4)=>OF_poly(OF_fn(x0,x1,x=>yc-A*Math.sin(2*Math.PI*(x-x0)/P)),col,w);
/* an index plot: r from -40 to 40 µm across w, n from 1.455 to 1.485 up h */
const OF_prof=(x0,y0,w,h,kind,col)=>{const X=r=>x0+(r+40)/80*w,Y=n=>y0+h-(n-1.455)/0.03*h;
 const p=kind==='step'?[[-40,1.46],[-25,1.46],[-25,1.48],[25,1.48],[25,1.46],[40,1.46]].map(q=>[X(q[0]),Y(q[1])]):OF_fn(-40,40,r=>Y(OF_n(r)),160).map(q=>[X(q[0]),q[1]]);
 return OF_L(x0,y0+h,x0+w,y0+h,'#ADB5BD',2)+OF_L(X(0),y0-4,X(0),y0+h,'#ADB5BD',2,'stroke-dasharray="5 5"')+OF_poly(p,col,5)};
/* V against λ for the worked fiber: λ 0.7..1.7 µm across w, V 0..4 up h */
const OF_vplot=(x0,y0,w,h,o={})=>{const X=l=>x0+(l-0.7)*w,Y=v=>y0+h-v/4*h;let s='';
 if(o.shade)s+=`<rect x="${X(1.15).toFixed(1)}" y="${Y(2.405).toFixed(1)}" width="${(X(1.7)-X(1.15)).toFixed(1)}" height="${(Y(0)-Y(2.405)).toFixed(1)}" fill="${GRN}" fill-opacity=".14"/>`;
 s+=OF_L(x0,Y(0),x0+w,Y(0),'#ADB5BD',3)+OF_L(x0,Y(0),x0,y0,'#ADB5BD',3)+OF_L(x0,Y(2.405),x0+w,Y(2.405),ORG,3,'stroke-dasharray="9 6"');
 s+=OF_poly(OF_fn(0.75,1.7,l=>Y(OF_K2/l)).map(q=>[X(q[0]),q[1]]),BLU,4);
 return {s,X,Y}};

