function EXTRA(R,ICON){
 /* hook: two fibers end-on at the same scale (cladding 125 µm): a 50 µm core and a 9 µm core */
 const end=(x,y,core,col,l1,l2)=>{const k=70/62.5;return `<g transform="translate(${x-190} ${y-80})">${OF_box(0,0,380,160,{fill:'#FFFFFF',st:col,sw:3,r:18})}
<circle cx="90" cy="80" r="70" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="3"/><circle cx="90" cy="80" r="${(core/2*k).toFixed(1)}" fill="${col}" fill-opacity=".85"/>
${OF_T(180,62,l1,{fs:24,fw:800,fill:col})}${OF_T(180,98,l2,{fs:24,fw:800,fill:col})}${OF_T(180,132,'cladding 125 µm',{fs:20,fill:OF_GREY})}</g>`};
 ICON.ofHookMM=(x,y)=>end(x,y,50,ORG,'data center','core 50 µm');
 ICON.ofHookSM=(x,y)=>end(x,y,9,BLU,'between cities','core ≈ 9 µm');
 /* recap pictures, about 420 x 330 each */
 ICON.ofProf=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${OF_prof(30,40,360,220,'step',BLU)}${OF_prof(30,40,360,220,'par',ORG)}
${OF_T(30,300,'step: V²/2',{fs:26,fw:800,fill:BLU})}${OF_T(390,300,'graded: V²/4',{fs:26,fw:800,a:'end',fill:ORG})}</g>`;
 ICON.ofCut=(x,y)=>{const P_=OF_vplot(40,30,350,230,{shade:1});return `<g transform="translate(${x-210} ${y-165})">${P_.s}<circle cx="${P_.X(1.15).toFixed(1)}" cy="${P_.Y(2.405).toFixed(1)}" r="10" fill="${ORG}"/>
${OF_T(P_.X(1.15)-14,P_.Y(2.405)-16,OF_s('λ','c'),{fs:28,fw:800,a:'end',fill:ORG})}${OF_T(390,P_.Y(2.405)-14,'V = 2.405',{fs:24,fw:800,a:'end',fill:ORG})}${OF_T(390,300,'single-mode for λ > '+OF_s('λ','c'),{fs:24,fw:800,a:'end',fill:GRN})}</g>`};
 ICON.ofSpd=(x,y)=>{const xc=200,env=xx=>Math.exp(-((xx-xc)*(xx-xc))/(2*55*55));return `<g transform="translate(${x-210} ${y-165})">
${OF_poly(OF_fn(20,400,xx=>180-80*env(xx)*Math.cos(2*Math.PI*(xx-xc)/34),240),BLU,3.5)}${OF_poly(OF_fn(60,340,xx=>180-80*env(xx),120),GRN,3,'stroke-dasharray="9 6"')}
${OF_arrow(230,60,350,60,BLU,4)}${OF_T(360,68,OF_s('v','p'),{fs:28,fw:800,fill:BLU})}${OF_arrow(230,290,330,290,GRN,4)}${OF_T(340,298,OF_s('v','g'),{fs:28,fw:800,fill:GRN})}
${OF_T(20,68,'crests',{fs:24,fw:800,fill:BLU})}${OF_T(20,298,'envelope',{fs:24,fw:800,fill:GRN})}</g>`};
}
